// app.js — вынесено из index.html (T-74, 24.08.2026)
// Блок COMPANIES ниже перегенерируется скриптом update_site.py при каждом
// обновлении каталога из Google Таблицы — см. update_site.py.

function submitForm() {
  const name = document.getElementById("f-name").value.trim();
  const phone = document.getElementById("f-phone").value.trim();
  if (!name || !phone) {
    alert("Заполните название компании и телефон/Telegram");
    return;
  }
  if (!document.getElementById("f-consent").checked) {
    alert("Нужно согласиться с политикой конфиденциальности и обработкой персональных данных");
    return;
  }
  const directions = document.getElementById("f-directions").value.trim();
  const site = document.getElementById("f-site").value.trim();
  const desc = document.getElementById("f-desc").value.trim();
  const msg = encodeURIComponent(
    "Заявка на добавление в каталог MyAvtoAgregator.ru\n\n" +
    "Компания: " + name + "\n" +
    "Контакт: " + phone + "\n" +
    (directions ? "Направления: " + directions + "\n" : "") +
    (site ? "Сайт/канал: " + site + "\n" : "") +
    (desc ? "О компании: " + desc : "")
  );
  window.open("https://t.me/My_Avto_Agregator?text=" + msg, "_blank");
  document.getElementById("form-success").style.display = "block";
  ["f-name","f-phone","f-directions","f-site","f-desc"].forEach(id => document.getElementById(id).value = "");
  document.getElementById("f-consent").checked = false;
}

// --- Массовая заявка по всем компаниям (задача #49) ---
// CloudPayments ещё не подключён (реквизиты/публичный ID появятся позже) —
// это ЗАГЛУШКА: cloudPaymentsCheckout() ничего не списывает по-настоящему,
// просто помечает заявку как "к оплате" и продолжает поток. Когда
// CloudPayments будет готов, здесь нужно заменить тело функции на
// настоящий вызов виджета, например:
//
//   const widget = new cp.CloudPayments();
//   widget.charge({ publicId: 'pk_...', amount: amountRub, currency: 'RUB',
//     description: 'Услуга подбора — рассылка запроса по компаниям',
//     accountId: phone, email: email }, onSuccess, onFail);
//
// email передаётся в кассу для отправки электронного чека (54-ФЗ) —
// CloudPayments поддерживает встроенную интеграцию с онлайн-кассой,
// свой отдельный чек генерировать не нужно, если чек включён в
// настройках кассы у провайдера. и вызывать onNext() только из
// onSuccess (сейчас onNext() вызывается сразу, без реальной оплаты).
function cloudPaymentsCheckout(amountRub, phone, email, onNext) {
  console.log("[CloudPayments STUB] онлайн-оплата ещё не подключена, пропускаю шаг оплаты", { amountRub, phone, email });
  onNext();
}

// Бэкенд задачи #49/#51 (telegram_bot_service.py) — вариант "личка бота,
// без общих групп" (10.08.2026, решение пользователя: клиент в общей
// группе видел бы чужие заявки, это неприемлемо). Пока бэкенд не
// задеплоен на VPS (нужен токен бота от @BotFather + systemd/nginx —
// см. PROJECT_STATE.md), MASS_REQUEST_API будет недоступен, поэтому ниже
// есть fallback на старое поведение (диплинк с готовым текстом в общий
// аккаунт), чтобы форма не ломалась до деплоя.
const MASS_REQUEST_API = "https://myavto-agregator.ru/api/mass-request";
const BOT_USERNAME = "MyAvtoAgregator_bot"; // реальный бот создан 12.08.2026, ждём деплоя backend'а на VPS (см. deploy/DEPLOY_BOT.md)

function submitMassRequest(event) {
  event.preventDefault();
  const name = document.getElementById("mr-name").value.trim();
  const phone = document.getElementById("mr-phone").value.trim();
  const email = document.getElementById("mr-email").value.trim();
  const direction = document.getElementById("mr-direction").value;
  const budget = document.getElementById("mr-budget").value.trim();
  const model = document.getElementById("mr-model").value.trim();
  const website = document.getElementById("mr-website").value; // T-21: honeypot, у людей всегда пусто
  if (!name || !phone || !direction) {
    alert("Заполните имя, телефон/Telegram и направление");
    return false;
  }
  if (!email || !email.includes("@")) {
    alert("Укажите email для связи");
    return false;
  }
  // Открываем вкладку СИНХРОННО, сразу по клику — это единственный момент,
  // когда браузер считает window.open() "инициированным пользователем" и не
  // блокирует его как всплывающее окно. Если открыть окно ПОСЛЕ ответа
  // fetch() (как было раньше), к этому моменту контекст клика уже утерян и
  // Safari/Chrome тихо блокируют окно — снаружи выглядит как "нажал
  // отправить, ничего не произошло", хотя заявка на сервере создаётся
  // успешно (баг найден 12.08.2026 через живой тест с пользователем).
  // Адрес подставляем в него позже, когда узнаем request_id/fallback-текст.
  const tgWindow = window.open("", "_blank");
  // T-20 (18.08.2026, по решению пользователя): пока не подключена
  // настоящая касса, услуга бесплатна — 0 вместо 990, чтобы сумма здесь
  // совпадала с тем, что видно в интерфейсе (см. .mr-price-old/.mr-price-free
  // выше). Когда CloudPayments будет готов — вернуть 990 здесь И убрать
  // зачёркивание цены в разметке одновременно, не порознь.
  cloudPaymentsCheckout(0, phone, email, () => {
    fetch(MASS_REQUEST_API, {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({name, phone, email, direction, budget, model, website})
    })
      .then(r => { if (!r.ok) throw new Error("backend error"); return r.json(); })
      .then(data => {
        const url = "https://t.me/" + (data.bot_username || BOT_USERNAME) + "?start=req_" + data.request_id;
        if (tgWindow) tgWindow.location.href = url; else window.open(url, "_blank");
      })
      .catch(() => {
        // Бэкенд ещё не задеплоен/недоступен — старое поведение как fallback,
        // чтобы клиент всё равно мог отправить заявку.
        const msg = encodeURIComponent(
          "Заявка на рассылку по всем компаниям (бесплатно, MyAvtoAgregator.ru)\n\n" +
          "Имя: " + name + "\n" +
          "Контакт: " + phone + "\n" +
          "Email: " + email + "\n" +
          "Направление: " + direction + "\n" +
          (budget ? "Бюджет: " + budget + "\n" : "") +
          (model ? "Что ищет: " + model : "")
        );
        const url = "https://t.me/My_Avto_Agregator?text=" + msg;
        if (tgWindow) tgWindow.location.href = url; else window.open(url, "_blank");
      })
      .finally(() => {
        document.getElementById("mr-success").style.display = "block";
        ["mr-name","mr-phone","mr-email","mr-budget","mr-model","mr-website"].forEach(id => document.getElementById(id).value = "");
        document.getElementById("mr-direction").value = "";
        document.getElementById("mr-consent").checked = false;
      });
  });
  return false;
}

