// T-60 (18.08.2026, по запросу пользователя): счётчик посетителей.
// Один POST на загрузку страницы — инкрементит и сразу возвращает
// актуальное число, подставляем в плейсхолдер #visitCount из .stats-bar
// (см. update_site.py — сама плашка генерируется там, число сюда
// приходит с бэкенда, не из Google Sheets). Если бэкенд недоступен —
// тихо оставляем "…", без alert'ов и сломанной страницы.
fetch("https://myavto-agregator.ru/api/visit", {method: "POST"})
  .then(r => { if (!r.ok) throw new Error("backend error"); return r.json(); })
  .then(data => {
    const el = document.getElementById("visitCount");
    if (el && typeof data.count === "number") el.textContent = data.count.toLocaleString("ru-RU");
  })
  .catch(() => {});
let rvSelectedRating = 0;
let rvCurrentCompany = null;

function reviewWordRu(n) {
  const n10 = n % 10, n100 = n % 100;
  if (n10 === 1 && n100 !== 11) return "отзыв";
  if (n10 >= 2 && n10 <= 4 && (n100 < 10 || n100 >= 20)) return "отзыва";
  return "отзывов";
}

function updateReviewStars() {
  document.querySelectorAll("#rvStars span").forEach(s => {
    s.classList.toggle("on", parseInt(s.dataset.star, 10) <= rvSelectedRating);
  });
}
document.getElementById("rvStars")?.addEventListener("click", (e) => {
  const star = e.target.closest("span[data-star]");
  if (!star) return;
  rvSelectedRating = parseInt(star.dataset.star, 10);
  updateReviewStars();
});

function openReviewModal(companyId) {
  const c = COMPANIES.find(x => x.id === companyId);
  if (!c) return;
  rvCurrentCompany = c;
  document.getElementById("reviewModalCompany").textContent = c.name;
  const items = c.reviewsList || [];
  document.getElementById("reviewModalList").innerHTML = items.map(r => {
    const stars = parseInt(r.rating, 10) || 0;
    return `<div class="review-item">
      <div class="review-item-head">
        <span class="review-item-author">${r.author}</span>
        <span class="review-item-stars">${"★".repeat(stars)}${"☆".repeat(5 - stars)}</span>
      </div>
      <div class="review-item-text">${r.text}</div>
      ${r.date ? `<div class="review-item-date">${r.date.split(" ")[0]}</div>` : ""}
    </div>`;
  }).join("");
  rvSelectedRating = 0;
  updateReviewStars();
  document.getElementById("rv-author").value = "";
  document.getElementById("rv-text").value = "";
  document.getElementById("rv-contact").value = "";
  document.getElementById("rv-website").value = "";
  document.getElementById("reviewModalForm").style.display = "";
  document.getElementById("reviewModalSuccess").classList.remove("open");
  document.getElementById("reviewModalOverlay").classList.add("open");
}

function closeReviewModal() {
  document.getElementById("reviewModalOverlay").classList.remove("open");
}

function submitReview(event) {
  event.preventDefault();
  if (!rvCurrentCompany) return false;
  const author = document.getElementById("rv-author").value.trim();
  const text = document.getElementById("rv-text").value.trim();
  const contact = document.getElementById("rv-contact").value.trim();
  const website = document.getElementById("rv-website").value; // T-21: honeypot
  if (!author || !text) {
    alert("Заполните имя и текст отзыва");
    return false;
  }
  if (!rvSelectedRating) {
    alert("Поставьте оценку от 1 до 5 звёзд");
    return false;
  }
  if (text.length < 10) {
    alert("Текст отзыва слишком короткий — расскажите чуть подробнее о своём опыте");
    return false;
  }
  fetch(REVIEW_API, {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
      company_id: rvCurrentCompany.id,
      company_name: rvCurrentCompany.name,
      author_name: author,
      rating: rvSelectedRating,
      text, contact, website
    })
  })
    .then(r => { if (!r.ok) throw new Error("backend error"); return r.json(); })
    .then(() => {
      document.getElementById("reviewModalForm").style.display = "none";
      document.getElementById("reviewModalSuccess").classList.add("open");
    })
    .catch(() => {
      alert("Не удалось отправить отзыв — попробуйте ещё раз чуть позже.");
    });
  return false;
}

