// Калькулятор растаможки — 01.09.2026 (T-61, часть "растаможка").
// Раньше это была функция calcPrice() с 4 захардкоженными строками-заглушками
// на страну — не расчёт, а таблица выдуманных чисел. Заменено на реальную
// формулу для физлица, ввозящего авто для личного пользования (не юрлицо,
// не коммерческий ввоз для перепродажи — это другая, более дорогая схема).
//
// Источники (проверены напрямую по первоисточникам 01.09.2026):
// - Пошлина: Решение Совета ЕЭК от 20.12.2017 №107 «Об отдельных вопросах,
//   связанных с товарами для личного пользования», Приложение №2, Таблица 2,
//   п.3 (легковые авто, ТН ВЭД 8703), с учётом изменений по 18.10.2024 №87.
//   https://eec.eaeunion.org/upload/medialibrary/48d/754bnati3u804penijmb0h866e5g6cng/Prilozhenie-2_107.pdf
// - Утильсбор: Постановление Правительства РФ от 26.12.2013 №1291, с изм.
//   от Постановления №1713 от 01.11.2025 (вступило в силу 01.12.2025) —
//   именно это изменение добавило порог по мощности (л.с.), не только по
//   объёму двигателя. http://government.ru/docs/all/161708/
// - Курс EUR/RUB: ЦБ РФ на 01.09.2026 — 100,5714 ₽. Захардкожен ниже,
//   НЕ обновляется автоматически — при использовании через несколько
//   месяцев курс нужно обновить вручную (EUR_RATE ниже).
//
// Важные ограничения (честно, не скрываем):
// - Ставки пошлины и коэффициент утильсбора верны только для физлица,
//   личное пользование, не для перепродажи. Юрлица/коммерческий ввоз
//   считаются иначе (в т.ч. отдельно НДС) — здесь не реализовано.
// - 01.09.2026 (уточнение T-116): изначально утильсбор считался только
//   в границах льготного порога (ДВС ≤3000см³ и ≤160 л.с.; электро/гибрид
//   ≤80 л.с.), а выше порога показывалось "считается индивидуально". Это
//   было неверно по духу (пользователь сразу столкнулся с этим на обычной
//   машине 1999см³/204 л.с.) — оказалось, что раздел I пп.3-4 Перечня
//   к ПП №1291 содержит ПОЛНУЮ прогрессивную таблицу коэффициентов именно
//   для физлиц/личного пользования (а не только льготную ставку), с явными
//   годовыми колонками 2024-2030. Прочитана целиком напрямую с
//   customs.gov.ru (см. UTIL_ICE_PERSONAL/UTIL_EV_PERSONAL ниже) — теперь
//   считаем полностью, а не только льготную часть.
// - Доставка — ориентировочная оценка (те же старые числа по стране, что
//   были в заглушке), не тариф конкретного перевозчика и не связана с
//   реальными объявлениями на площадках (Encar/Mobile.de/китайские
//   агрегаторы) — это отдельная, не реализованная часть задачи T-61
//   (нужен бэкенд-прокси из-за CORS + вопрос легальности парсинга по ToS
//   площадок), пользователь пока вводит цену авто сам.

// T-117 (01.09.2026): курсы ЦБ РФ для конвертации стоимости авто ($/¥/₩/₽)
// в EUR (формула пошлины — в EUR по тексту Решения №107, см. выше) и для
// отображения. Это СИД-значения на момент написания — update_site.py при
// каждом обычном прогоне подставляет сюда актуальные курсы напрямую с
// cbr.ru (см. fetch_cbr_rates.py). ВАЖНО (уже наступали на эти грабли,
// T-117-fix): не пиши в этом комментарии буквально код объявления
// следующей строки в кавычках — update_site.py ищет его наивным find()
// по всему файлу, и находит ПЕРВОЕ совпадение, даже если оно внутри
// комментария, а не настоящий код. Из-за этого объявление CBR_RATES ниже
// один раз склеилось с этим комментарием, и весь калькулятор упал
// (EUR_RATE = CBR_RATES.EUR бросал ReferenceError, TDZ на EUR_RATE).
// update_site.py теперь ищет с переводом строки перед "const", но
// всё равно не переписывай следующую строку буквально нигде выше неё.
const CBR_RATES = {"_date": "02.09.2026", "USD": 86.753, "EUR": 100.5988, "CNY": 12.897, "KRW": 0.063157};

const EUR_RATE = CBR_RATES.EUR; // курс EUR нужен формуле пошлины отдельно от остальных валют

// Доставка — цифры от пользователя на 01.09.2026, каждая в той валюте, в
// которой реально выставляют счёт на этом направлении (не всегда рубли).
// В рубли переводится в момент расчёта через CBR_RATES, а не один раз
// захардкожено — так сумма не протухнет, когда курс обновится отдельно.
// ОАЭ убрано (не актуально), добавлены Грузия и Киргизия (01.09.2026).
const DELIVERY_FROM = {
  korea: { amount: 1500, currency: "USD" }, // до Владивостока
  china: { amount: 150000, currency: "RUB" },
  japan: { amount: 200000, currency: "RUB" },
  usa: { amount: 350000, currency: "RUB" },
  europe: { amount: 5500, currency: "EUR" },
  georgia: { amount: 90000, currency: "RUB" },
  kyrgyzstan: { amount: 1500, currency: "USD" },
};

// Пакет услуг брокера — не растаможка сама по себе (та считается отдельно
// выше), а сопутствующие обязательные процедуры: хранение на СВХ (склад
// временного хранения), оценочная экспертиза (нужна, когда таможенная
// стоимость не подтверждена инвойсом), СБКТС (свидетельство о безопасности
// конструкции — обязательно для машин без ОТТС), ЭПТС (электронный паспорт
// ТС, без него не поставить на учёт) и оформление/подача расчёта
// утилизационного сбора в таможню. Фиксированная ориентировочная сумма от
// пользователя — не выведена из формулы, честно помечена как ориентир.
const BROKER_SERVICES_RUB = 110000;
const BROKER_SERVICES_LABEL = "Услуги брокера (СВХ, оценочная экспертиза, СБКТС, ЭПТС, оформление утильсбора)";

// Комиссия экспортёра — % от стоимости авто, который берёт сторона,
// организующая покупку/вывоз на площадке продавца. От пользователя указана
// только для направления "Европа" (де-факто Германия — основной рынок
// экспортёров на этом направлении), 01.09.2026. Для остальных стран не
// задана — не выдумываем ставку, комиссия там просто не учитывается (не то
// же самое, что "не удалось посчитать": для других стран этот пункт
// действительно не понадобился пользователю).
const EXPORTER_COMMISSION_RATE = 0.06; // 6%, только для country === 'europe'

// Комиссия импортёра — фиксированная ориентировочная сумма (не % от
// стоимости, в отличие от комиссии экспортёра выше), от пользователя,
// применяется независимо от страны — это плата за организацию сделки на
// стороне ввоза, не привязана к конкретному рынку продавца.
const IMPORTER_COMMISSION_RUB = 150000;

// T-123 (02.09.2026, по запросу пользователя — "таможенное оформление тоже
// добавить нужно, в зависимости от стоимости данный платёж меняется").
// Таможенный сбор за таможенные операции — Постановление Правительства РФ
// №1638 от 23.10.2025, действует с 01.01.2026 (ставки выросли на 11,7-15,3%
// по сравнению с 2025, верхний порог партии — с 7 до 10 млн₽). Сверено
// по двум независимым источникам (petercargo.ru, ost-term.ru — оба цитируют
// одинаковые 8 диапазонов, дата публикации 2026), это отдельный от пошлины
// и НДС платёж, применяется одинаково к любому ввозу (физлицо/юрлицо,
// легковой/грузовой) — привязан только к заявленной таможенной стоимости.
// ВАЖНО: сам текст Постановления №1638 напрямую не открывали (нет доступа
// к publication.pravo.gov.ru из песочницы), это вторичный источник — по
// возможности сверить с оригиналом при следующей ежемесячной проверке.
const CUSTOMS_FEE_BANDS = [
  { max: 200000, fee: 1231 },
  { max: 450000, fee: 2462 },
  { max: 1200000, fee: 4924 },
  { max: 2700000, fee: 13541 },
  { max: 4200000, fee: 18465 },
  { max: 5500000, fee: 21344 },
  { max: 10000000, fee: 49240 },
  { max: null, fee: 73860 },
];

function customsFeeRub(priceRub) {
  if (!priceRub) return null; // без заявленной стоимости сбор не определить
  return findBand(CUSTOMS_FEE_BANDS, priceRub, 'max').fee;
}

// T-124 (02.09.2026, по запросу пользователя — "пикап" после уточнения про
// категорию N1). Пикапы и лёгкие грузовики попадают под ТН ВЭД 8704, а не
// 8703 — критерии из Решения Комиссии ТС №751 от 18.11.2011 (число осей,
// полная масса, отношение длины платформы к базе, расчётная масса груза
// vs пассажиров — не "визуально грузовой"/"визуально легковой"). Раздел
// I калькулятора (M1) сюда НЕ применим.
//
// Утильсбор — раздел II той же страницы customs.gov.ru ("Транспортные
// средства... категорий N1, N2 и N3"), коэффициенты только по массе, БЕЗ
// деления по мощности/объёму (в отличие от M1) — сверено напрямую по живой
// странице, item 5/6/7 (до 2,5т / 2,5-3,5т / 3,5-5т — тяжелее не
// поддерживаем, не нужно для пикапов). ВАЖНО: у этой таблицы, в отличие от
// M1, коэффициенты заполнены уже с 2024 года (не "-" как у M1) — значит и
// логика "минимальный год 2025" здесь не годится, берём с 2024.
//
// В отличие от M1 у грузовых НЕТ отдельной "льготной" ставки для физлиц —
// в разделе II нет подраздела "ввозимые физическими лицами для личного
// пользования" вообще (проверено — все вхождения "личного пользования" на
// странице лежат либо в разделе I у M1, либо дальше у других категорий,
// не внутри диапазона раздела II). Поэтому для N1 расчёт одинаковый для
// физ- и юрлица — importerType здесь не используется.
const UTIL_TRUCK = [
  { maxMass: 2500, byYear: { "2024": [5.07, 7.36], "2025": [5.57, 8.1], "2026": [6.13, 8.91], "2027": [6.74, 9.8], "2028": [7.42, 10.78], "2029": [8.16, 11.85], "2030": [8.97, 13.04] } },
  { maxMass: 3500, byYear: { "2024": [5.46, 7.94], "2025": [6, 8.73], "2026": [6.6, 9.61], "2027": [7.26, 10.57], "2028": [7.99, 11.62], "2029": [8.79, 12.79], "2030": [9.67, 14.06] } },
  { maxMass: 5000, byYear: { "2024": [5.71, 8.5], "2025": [6.28, 9.35], "2026": [6.91, 10.29], "2027": [7.6, 11.31], "2028": [8.36, 12.44], "2029": [9.2, 13.69], "2030": [10.12, 15.06] } },
];

function utilFeeTruckRub(age, maxMass) {
  const year = String(Math.max(2024, Math.min(2030, new Date().getFullYear())));
  const ageKey = age === 'lt3' ? 0 : 1;
  const band = findBand(UTIL_TRUCK, maxMass, 'maxMass');
  const pair = band.byYear[year];
  return pair ? 20000 * pair[ageKey] : null;
}

// Пошлина для N1 — ОДИН источник (ost-term.ru, брокер, не сверено по
// второй независимой площадке в отличие от таблицы таможенного сбора
// выше) — 15% бензин / 10% дизель, флэт, без деления по возрасту/массе/
// объёму двигателя. Честно ниже эпистемический статус этой цифры, чем у
// остального в файле — стоит перепроверить по ЕТТ ЕАЭС напрямую при
// возможности. НДС 22% — как обычно, от (стоимость + пошлина). Акциза
// НЕТ — грузовые категории N1 не облагаются акцизом (подтверждено тем же
// источником: "не применяется ставка акциза").
const DUTY_TRUCK_RATE = { petrol: 0.15, diesel: 0.10 };

function dutyTruckRub(fuelType, priceRub) {
  const duty = priceRub * DUTY_TRUCK_RATE[fuelType];
  const vat = (priceRub + duty) * 0.22;
  return { duty, vat, total: duty + vat };
}

// currency !== "RUB" здесь означает "нужно конвертировать по курсу ЦБ РФ" —
// та же функция конвертации, что и для стоимости авто, чтобы не дублировать
// логику (см. currency === 'RUB' ? ... в calcCustoms).
function toRub(amount, currency) {
  return currency === "RUB" ? amount : amount * CBR_RATES[currency];
}

