// полосе до 58,84 кВт, где у физлица флэт-ставка 0,17/0,26, а у юрлица —
// обычная прогрессия. Берём копию личной таблицы и подменяем первую полосу.
const UTIL_EV_LEGAL = JSON.parse(JSON.stringify(UTIL_EV_PERSONAL));
UTIL_EV_LEGAL[0] = {"maxKw": 58.84, "byYear": {"2024": [null, null], "2025": [33.37, 58.7], "2026": [40.04, 70.44], "2027": [44.05, 77.48], "2028": [48.45, 85.23], "2029": [53.3, 93.76], "2030": [58.63, 103.13]}};

// Пошлина (ЕТТ ЕАЭС, Решение №54 от 16.07.2012, коммерческий ввоз юрлицом)
// — только бензиновый двигатель (ТН ВЭД 8703 21-24), сверено по drom.ru
// (правильно отрендеренная, не битая кодировка страница — исходные числа
// совпадают с общеизвестной таблицей ЕТТ, её же приводят calcus.ru,
// terminalzm.ru и другие калькуляторы растаможки). Дизель (8703 31-33)
// и гибрид отдельно НЕ сверены — считаются по этой же бензиновой таблице
// как приближение, честно помечено в интерфейсе. Формат банда: [maxCm3,
// ставка €/см³] по возрастанию, последний с maxCm3=Infinity — открытый.
const DUTY_LEGAL_ICE = {
  lt3: { pct: 0.25, bands: [[1000, 1], [1500, 1.1], [1800, 1.25], [2300, 1.8], [3000, 1.8], [Infinity, 2.35]] },
  '3-7': { pct: 0.25, bands: [[1000, 0.45], [1500, 0.5], [1800, 0.45], [3000, 0.55], [Infinity, 1]] },
  gt7: { pct: null, bands: [[1000, 1.4], [1500, 1.5], [1800, 1.6], [3000, 2.2], [Infinity, 3.2]] },
};

function rateFromCm3Bands(bands, cm3) {
  for (const [max, rate] of bands) { if (cm3 <= max) return rate; }
  return bands[bands.length - 1][1];
}

// Пошлина для юрлица (ДВС/гибрид): для lt3/3-7 — БОЛЬШЕЕ из (% от стоимости)
// и (минимальная ставка €/см³), как и у физлица до 3 лет; для gt7 — чистая
// ставка €/см³ без %, стоимость авто не нужна.
function dutyLegalIceEur(ageBucketLegal, valueEur, cm3) {
  const cfg = DUTY_LEGAL_ICE[ageBucketLegal];
  const rate = rateFromCm3Bands(cfg.bands, cm3);
  if (cfg.pct === null) return cm3 * rate;
  return Math.max(valueEur * cfg.pct, cm3 * rate);
}

// В отличие от физлица (упрощённый порядок — только пошлина+утильсбор),
// юрлицо при коммерческом ввозе платит полный стандартный набор: пошлина +
// акциз (НК РФ ст.193, применяется независимо от типа ввозящего) + НДС 22%
// от (стоимость+пошлина+акциз). Возвращает разбивку, а не только сумму —
// нужно показать все 3 строки отдельно в интерфейсе.
function dutyLegalIceRub(ageBucketLegal, priceRub, cm3, hp) {
  const valueEur = priceRub / EUR_RATE;
  const dutyRub = dutyLegalIceEur(ageBucketLegal, valueEur, cm3) * EUR_RATE;
  const excise = exciseRub(hp);
  const vat = (priceRub + dutyRub + excise) * 0.22;
  return { dutyRub, excise, vat, total: dutyRub + excise + vat };
}

// Пошлина для авто от 3 до 5 лет и старше 5 лет — фиксированная ставка
// €/см³ по диапазону объёма двигателя, стоимость авто не участвует.
function dutyRatePerCm3(age, cm3) {
  const bands3to5 = [[1000,1.5],[1500,1.7],[1800,2.5],[2300,2.7],[3000,3],[Infinity,3.6]];
  const bandsOver5 = [[1000,3],[1500,3.2],[1800,3.5],[2300,4.8],[3000,5],[Infinity,5.7]];
  const bands = age === '3-5' ? bands3to5 : bandsOver5;
  for (const [max, rate] of bands) { if (cm3 <= max) return rate; }
  return bands[bands.length - 1][1];
}

// Пошлина для авто до 3 лет — применяется БОЛЬШЕЕ из (% от стоимости) и
// (минимальная ставка €/см³) — так прямо указано в Решении №107.
function dutyEurUnder3(valueEur, cm3) {
  const bands = [
    [8500, 0.54, 2.5],
    [16700, 0.48, 3.5],
    [42300, 0.48, 5.5],
    [84500, 0.48, 7.5],
    [169000, 0.48, 15],
    [Infinity, 0.48, 20],
  ];
  for (const [max, pct, minRate] of bands) {
    if (valueEur <= max) return Math.max(valueEur * pct, cm3 * minRate);
  }
}

const HP_TO_KW = 1 / 1.35962; // л.с. -> кВт, обратный коэффициент из самого документа ФТС (160 л.с. = 117,68 кВт)
const KW_TO_HP = 1.35962;

// РЕКОНСТРУКЦИЯ, НЕ ОФИЦИАЛЬНАЯ ФОРМУЛА (01.09.2026, по запросу пользователя
// "расчет электричек давай сделаем"). Решение №107 для чистых электромобилей
// (ТН ВЭД 8703 80 000, физлицо, личное пользование) прямо говорит только
// "пошлина в виде совокупного таможенного платежа" — без формулы внутри
// самого документа. Решения №39/№111/№35, на которые мы раньше ссылались
// как на возможный источник формулы, оказались НЕ про это — №39 про квоты
// беспощлинного ввоза для граждан Беларуси/Армении/Киргизии и вообще
// утратило силу 08.12.2023, №35 про снятие ограничений на уже льготно
// ввезённые машины. К формуле для рядового ввоза физлицом отношения не
// имеют — проверено напрямую по текстам (eec.eaeunion.org, alta.ru).
//
// Ниже — реконструкция по независимо совпадающим разборам таможенных
// брокеров (ucsol.ru, moscowteslaclub.ru и др.): пошлина 15% от таможенной
// стоимости + акциз по мощности (НК РФ ст.193 п.1 пп.27-33, ставки по
// диапазону мощности) + НДС 22% от (стоимость + пошлина + акциз). Утильсбор
// сюда не входит — он уже считается отдельно (UTIL_EV_PERSONAL выше) и
// это часть, подтверждённая напрямую по customs.gov.ru, а не реконструкция.
// НЕ включён таможенный сбор за операции (обычно несколько тысяч ₽,
// зависит от стоимости) — точную таблицу не сверяли, отдельно не считаем,
// чтобы не плодить ещё одну неподтверждённую цифру.
//
// Ставки акциза — НК РФ ст.193, диапазоны мощности официальные (сверены
// по тексту закона), сами суммы где удалось — ставки на 2026 год (индексация
// Федеральным законом №425-ФЗ от 28.11.2025), где НЕ удалось подтвердить
// ставку именно на 2026 — взята последняя подтверждённая (2025 год),
// то есть это, вероятно, НЕДООЦЕНКА для диапазонов 200-300, 400-500,
// свыше 500 л.с. — отмечено в комментарии к каждой строке.
const EXCISE_RUB_PER_HP = [
  { maxHp: 90, rate: 0 },
  { maxHp: 150, rate: 64 }, // 2026 год, подтверждено
  { maxHp: 200, rate: 613 }, // 2026 год, подтверждено
  { maxHp: 300, rate: 940 }, // ставка 2025 года — 2026 не подтверждена, вероятно занижено
  { maxHp: 400, rate: 1711 }, // 2026 год, подтверждено
  { maxHp: 500, rate: 1659 }, // ставка 2025 года — 2026 не подтверждена, вероятно занижено
  { maxHp: null, rate: 1713 }, // ставка 2025 года — 2026 не подтверждена, вероятно занижено
];

function exciseRub(hp) {
  const band = findBand(EXCISE_RUB_PER_HP, hp, 'maxHp');
  return hp * band.rate;
}

// Реконструированный СТП для электромобиля: пошлина 15% + акциз + НДС 22%.
// hp здесь — обязательно л.с. (не кВт), т.к. НК РФ считает акциз в л.с.
function electricDutyRub(priceRub, hp) {
  const customsDuty = priceRub * 0.15;
  const excise = exciseRub(hp);
  const vatBase = priceRub + customsDuty + excise;
  const vat = vatBase * 0.22;
  return customsDuty + excise + vat;
}

// Ищет первую полосу, где value <= порог (null-порог = последняя, безлимитная полоса).
// Полосы в таблицах отсортированы по возрастанию порога — так же, как в оригинале ФТС.
function findBand(bands, value, key) {
  for (const b of bands) {
    if (b[key] === null || value <= b[key]) return b;
  }
  return bands[bands.length - 1];
}

// Утильсбор по официальной таблице (не только льготная ставка — см. комментарий
// выше про уточнение T-116). ageKey: 0 = "новое" (наш возраст "до 3 лет"),
// 1 = "старше 3 лет" (наши "3-5" и "старше 5" — в таблице ФТС это ОДНА категория,
// отдельной строки для "старше 5 лет" в ней нет).
// importerType: 'physical' (по умолчанию) — таблицы п.3/п.4 (личное
// пользование); 'legal' — таблицы п.1/п.2 (общая/коммерческая), T-122.
function utilFeeRub(age, engineType, cm3, kw, importerType) {
  const year = String(Math.max(2025, Math.min(2030, new Date().getFullYear())));
  const ageKey = age === 'lt3' ? 0 : 1;
  const isLegal = importerType === 'legal';

  const iceTable = isLegal ? UTIL_ICE_LEGAL : UTIL_ICE_PERSONAL;
  const evTable = isLegal ? UTIL_EV_LEGAL : UTIL_EV_PERSONAL;
  const powerBands = engineType === 'ice'
    ? findBand(iceTable, cm3, 'maxCm3').bands
    : evTable;

  const band = findBand(powerBands, kw, 'maxKw');
  const pair = band.byYear[year];
  const coef = pair ? pair[ageKey] : null;
  return coef === null ? null : 20000 * coef;
}

function fmtRub(n) {
  return Math.round(n).toLocaleString('ru-RU') + ' ₽';
}

function calcCustoms() {
  const vehicleCategory = document.getElementById('calcVehicleCategory').value; // 'm1' | 'n1'
  const importerType = document.getElementById('calcImporterType').value; // 'physical' | 'legal'
  const isLegal = importerType === 'legal';
  const country = document.getElementById('calcCountry').value;
  const age = document.getElementById('calcAge').value; // lt3 | 3-5 | 5-7 | gt7
  const cm3 = parseFloat(document.getElementById('calcVolume').value);
  const engineType = document.getElementById('calcEngineType').value;
  const powerInput = parseFloat(document.getElementById('calcPower').value);
  const powerUnit = document.getElementById('calcPowerUnit').value; // 'hp' или 'kw'
  const kw = powerUnit === 'kw' ? powerInput : powerInput * HP_TO_KW;
  const priceInput = parseFloat(document.getElementById('calcValue').value);
  const currency = document.getElementById('calcCurrency').value;
  // CBR_RATES хранит курс "рублей за 1 единицу валюты" (для RUB — считаем
  // курс 1, конвертация не нужна). Одна и та же введённая сумма всегда
  // приводится к рублям здесь один раз, дальше по коду (дальше — все
  // формулы) везде используется уже priceRub, как и раньше.
  const priceRub = currency === 'RUB' ? priceInput : priceInput * CBR_RATES[currency];

  const labelEl = document.querySelector('#calcResultBlock .calc-label');
  const resultEl = document.getElementById('calcResult');
  const breakdownEl = document.getElementById('calcBreakdown');

  // T-124: пикап/грузовик до 5т — отдельная ветка с самого начала, поля и
  // формулы у M1 (легковые) и N1 (грузовые) не пересекаются вообще.
  if (vehicleCategory === 'n1') {
    const fuelType = document.getElementById('calcTruckFuel').value; // 'petrol' | 'diesel'
    const maxMass = parseFloat(document.getElementById('calcTruckMass').value);
    if (!maxMass) {
      labelEl.textContent = 'Выберите массу транспортного средства';
      resultEl.textContent = '—';
      breakdownEl.innerHTML = '';
      return;
    }
    if (!priceRub) {
      labelEl.textContent = 'Укажите стоимость авто — пошлина и НДС для N1 считаются от неё';
      resultEl.textContent = '—';
      breakdownEl.innerHTML = '';
      return;
    }
    const d = dutyTruckRub(fuelType, priceRub);
    const util = utilFeeTruckRub(age, maxMass);
    const deliveryInfo = DELIVERY_FROM[country];
    const delivery = toRub(deliveryInfo.amount, deliveryInfo.currency);
    const broker = BROKER_SERVICES_RUB;
    const exporterCommission = country === 'europe' ? priceRub * EXPORTER_COMMISSION_RATE : 0;
    const importerCommission = IMPORTER_COMMISSION_RUB;
    const customsFee = customsFeeRub(priceRub);

    labelEl.textContent = 'Пошлина + НДС + утильсбор + доставка + комиссии (грузовой N1, см. расшифровку)';
    const CURRENCY_SYMBOL = { USD: '$', EUR: '€', CNY: '¥', KRW: '₩', RUB: '₽' };
    const lines = [];
    lines.push(`Пошлина (${fuelType === 'diesel' ? '10%, дизель' : '15%, бензин'} от таможенной стоимости — источник один, не сверено по второй площадке): ${fmtRub(d.duty)}`);
    lines.push(`НДС 22% (акциза для N1 нет): ${fmtRub(d.vat)}`);
    lines.push(util !== null
      ? `Утильсбор (по массе, категория N1): ${fmtRub(util)}`
      : 'Утильсбор: не удалось рассчитать');
    lines.push(customsFee !== null ? `Таможенный сбор за операции: ${fmtRub(customsFee)}` : '');
    const deliveryOrig = deliveryInfo.currency === 'RUB'
      ? ''
      : ` (${CURRENCY_SYMBOL[deliveryInfo.currency]}${deliveryInfo.amount.toLocaleString('ru-RU')}, по курсу ЦБ РФ на ${CBR_RATES._date})`;
    lines.push(`Доставка: от ${fmtRub(delivery)}${deliveryOrig} — ориентировочно`);
    if (country === 'europe') {
      lines.push(`Комиссия экспортёра (Германия, ${EXPORTER_COMMISSION_RATE * 100}% от стоимости авто): ${fmtRub(exporterCommission)}`);
    }
    lines.push(`Комиссия импортёра: от ${fmtRub(importerCommission)} — ориентировочно`);
    lines.push(`${BROKER_SERVICES_LABEL}: от ${fmtRub(broker)} — ориентировочно`);
    breakdownEl.innerHTML = lines.filter(Boolean).join('<br>');

    if (util !== null) {
      resultEl.textContent = `от ${fmtRub(d.total + util + (customsFee || 0) + delivery + broker + exporterCommission + importerCommission)}`;
    } else {
      const known = d.total + (customsFee || 0) + delivery + broker + exporterCommission + importerCommission;
      resultEl.textContent = `от ${fmtRub(known)} + то, что считается индивидуально`;
    }
    return;
  }

  const needsVolume = engineType !== 'electric'; // у электромобиля нет см³
  if (!powerInput || (needsVolume && !cm3)) {
    labelEl.textContent = 'Заполните параметры выше';
    resultEl.textContent = '—';
    breakdownEl.innerHTML = '';
    return;
  }

  // T-122: у физлица (упрощённый порядок) цена авто нужна для пошлины
  // только "до 3 лет" — дальше идёт фиксированная ставка €/см³, стоимость
  // не участвует, а акциза/НДС у физлица вообще нет. У юрлица цена нужна
  // ВСЕГДА, даже "старше 7 лет" (где сама пошлина — чистая ставка €/см³ и
  // формально цену не использует) — потому что НДС (dutyLegalIceRub)
  // считается от суммы (стоимость + пошлина + акциз), и без цены НДС
  // получится заниженным на всю стоимость авто. Раньше здесь было
  // "age !== 'gt7'" — баг, поймал сам на тестовом расчёте перед деплоем.
  const iceNeedsPrice = needsVolume && (isLegal ? true : age === 'lt3');
  if (iceNeedsPrice && !priceRub) {
    labelEl.textContent = isLegal
      ? 'Для юрлица укажите стоимость авто — нужна для акциза и НДС даже при пошлине по фиксированной ставке'
      : 'Для авто младше 3 лет укажите стоимость';
    resultEl.textContent = '—';
    breakdownEl.innerHTML = '';
    return;
  }
  // Комиссия экспортёра (см. EXPORTER_COMMISSION_RATE ниже) — % от
  // стоимости авто, без цены её не посчитать, даже если для пошлины
  // цена в этом возрастном диапазоне не нужна.
  if (country === 'europe' && !priceRub) {
    labelEl.textContent = 'Для Европы укажите стоимость авто — нужна для комиссии экспортёра';
    resultEl.textContent = '—';
    breakdownEl.innerHTML = '';
    return;
  }
  // Для электро формула (пошлина+акциз+НДС) считается от стоимости авто
  // всегда, для обоих типов ввоза — в отличие от ДВС, где цена нужна не
  // всегда (см. iceNeedsPrice выше).
  if (engineType === 'electric' && !priceRub) {
    labelEl.textContent = 'Для электромобиля укажите стоимость авто — нужна для расчёта пошлины';
    resultEl.textContent = '—';
    breakdownEl.innerHTML = '';
    return;
  }

  const hpForExcise = powerUnit === 'kw' ? kw * KW_TO_HP : powerInput;

  // Возраст для формулы пошлины физлица — только 3 категории (Решение
  // №107 не знает "5-7"/"старше 7", это чисто юрлицовское деление ЕТТ):
  // "5-7" и "старше 7" у физлица считаются как "старше 5" (dutyRatePerCm3
  // сам разруливает 3-5 vs остальное).
  const physicalAgeBucket = age === 'lt3' ? 'lt3' : (age === '3-5' ? '3-5' : 'gt5');
  // Возраст для юрлица — наоборот, "3-5" и "5-7" дают ОДНУ и ту же ставку
  // (см. DUTY_LEGAL_ICE['3-7'], сверено по drom.ru — для бензина эти два
  // официальных под-пункта 1.1.2/1.1.3 численно идентичны).
  const legalAgeBucket = age === 'lt3' ? 'lt3' : (age === 'gt7' ? 'gt7' : '3-7');

  let dutyTotal, dutyLine, extraLines = [];
  if (engineType === 'electric') {
    // Одна и та же формула для обоих типов ввоза (15% пошлина + акциз по
    // мощности + 22% НДС) — но эпистемический статус разный: для юрлица
    // это ПОДТВЕРЖДЁННАЯ официальная ставка (Решение СЕЭК №80 от
    // 14.09.2021, ТН ВЭД 8703 80 000, 15% для РФ), для физлица — по-прежнему
    // РЕКОНСТРУКЦИЯ (см. комментарий у electricDutyRub выше), т.к. прямой
    // нормы для личного пользования электро в Решении №107 нет.
    dutyTotal = electricDutyRub(priceRub, hpForExcise);
    dutyLine = isLegal
      ? `Пошлина 15% + акциз по мощности + НДС 22% (Решение СЕЭК №80 от 14.09.2021, ТН ВЭД 8703 80 000): ${fmtRub(dutyTotal)}`
      : `Пошлина + акциз + НДС (реконструкция для электро — 15% + акциз по мощности + 22% НДС, НЕ прямая норма закона для физлиц, сверьте у брокера): ${fmtRub(dutyTotal)}`;
  } else if (isLegal) {
    // Юрлицо, ДВС/гибрид — полный стандартный набор: пошлина ЕТТ + акциз +
    // НДС отдельными строками (см. dutyLegalIceRub выше).
    const d = dutyLegalIceRub(legalAgeBucket, priceRub, cm3, hpForExcise);
    dutyTotal = d.total;
    dutyLine = `Пошлина (ЕТТ ЕАЭС, ${legalAgeBucket === 'gt7' ? 'фикс. ставка €/см³' : '25% от стоимости или мин. €/см³, что больше'}): ${fmtRub(d.dutyRub)}`;
    extraLines = [
      `Акциз по мощности (НК РФ ст.193): ${fmtRub(d.excise)}`,
      `НДС 22% (от стоимости + пошлины + акциза): ${fmtRub(d.vat)}`,
    ];
  } else {
    // Физлицо, ДВС/гибрид — как раньше, без отдельного акциза/НДС
    // (упрощённый порядок для личного пользования их не выделяет).
    dutyTotal = age === 'lt3'
      ? dutyEurUnder3(priceRub / EUR_RATE, cm3) * EUR_RATE
      : dutyRatePerCm3(physicalAgeBucket, cm3) * cm3 * EUR_RATE;
    dutyLine = `Пошлина: ${fmtRub(dutyTotal)}`;
  }

  const util = utilFeeRub(age, engineType, cm3 || 0, kw, importerType);
  const deliveryInfo = DELIVERY_FROM[country];
  const delivery = toRub(deliveryInfo.amount, deliveryInfo.currency);
  const broker = BROKER_SERVICES_RUB;
  const exporterCommission = country === 'europe' ? priceRub * EXPORTER_COMMISSION_RATE : 0;
  const importerCommission = IMPORTER_COMMISSION_RUB;
  const customsFee = customsFeeRub(priceRub); // T-123, null если стоимость не указана

  labelEl.textContent = 'Пошлина + утильсбор + доставка + комиссии + услуги брокера (см. расшифровку)';

  const CURRENCY_SYMBOL = { USD: '$', EUR: '€', CNY: '¥', KRW: '₩', RUB: '₽' };

  const lines = [];
  lines.push(dutyLine, ...extraLines);
  lines.push(util !== null
    ? `Утильсбор: ${fmtRub(util)}`
    : 'Утильсбор: не удалось рассчитать для этих параметров — проверьте ввод или уточняйте у компании из каталога');
  lines.push(customsFee !== null
    ? `Таможенный сбор за операции: ${fmtRub(customsFee)}`
    : 'Таможенный сбор за операции: укажите стоимость авто, чтобы посчитать (зависит от диапазона таможенной стоимости)');
  const deliveryOrig = deliveryInfo.currency === 'RUB'
    ? ''
    : ` (${CURRENCY_SYMBOL[deliveryInfo.currency]}${deliveryInfo.amount.toLocaleString('ru-RU')}, по курсу ЦБ РФ на ${CBR_RATES._date})`;
  lines.push(`Доставка: от ${fmtRub(delivery)}${deliveryOrig} — ориентировочно`);
  if (country === 'europe') {
    lines.push(`Комиссия экспортёра (Германия, ${EXPORTER_COMMISSION_RATE * 100}% от стоимости авто): ${fmtRub(exporterCommission)}`);
  }
  lines.push(`Комиссия импортёра: от ${fmtRub(importerCommission)} — ориентировочно`);
  lines.push(`${BROKER_SERVICES_LABEL}: от ${fmtRub(broker)} — ориентировочно`);
  breakdownEl.innerHTML = lines.join('<br>');

  if (dutyTotal !== null && util !== null) {
    resultEl.textContent = `от ${fmtRub(dutyTotal + util + (customsFee || 0) + delivery + broker + exporterCommission + importerCommission)}`;
  } else {
    const known = (dutyTotal || 0) + (util || 0) + (customsFee || 0) + delivery + broker + exporterCommission + importerCommission;
    resultEl.textContent = `от ${fmtRub(known)} + то, что считается индивидуально`;
  }
}

function toggleFaq(el) {
  el.classList.toggle('open');
}

// T-124: переключение между полями M1 (объём/тип двигателя/мощность) и
// N1 (тип топлива/масса) — показываем только те, что реально участвуют
// в формуле выбранной категории. Поле стоимости авто (calcValueRow) —
// общее для обеих категорий, всегда видимое (пробовали прятать под
// чекбокс "для экономии места" 02.09.2026, пользователь тут же попросил
// вернуть постоянную видимость — см. TASKS.md T-125).
function toggleVehicleCategory() {
  const isTruck = document.getElementById('calcVehicleCategory').value === 'n1';
  document.getElementById('calcM1Fields').style.display = isTruck ? 'none' : '';
  document.getElementById('calcN1Fields').style.display = isTruck ? '' : 'none';
  calcCustoms();
}

