// Ранжирование карточек — 14.08.2026, по запросу пользователя (раньше
// порядок = порядок строк в Google Таблице, featured влиял только на
// бейдж, но не на позицию). Приоритет по убыванию:
// 1. featured (ручной буст, ставится точечно, например для новых/особо
//    проверенных компаний) — единственная всегда-featured сейчас MY Avto
//    (собственная компания владельца), поэтому она и остаётся первой.
// 2. онбордилась ли компания в Telegram-боте (нажала /start) — прямой
//    стимул для компаний: активнее в боте -> выше в каталоге, не только
//    приоритет в заявках.
// 3. подтверждена ли компания в ЕГРЮЛ (egrulVerified) — честный сигнал
//    доверия для покупателя.
// 4. "активность" — сколько площадок у компании реально заполнено (сайт,
//    соцсети, маркетплейсы, карты, наличие отзывов) — чем полнее профиль,
//    тем выше. Рейтинг (rating/reviews) сознательно НЕ используется как
//    сигнал сам по себе — у большинства компаний это ещё не проверенная
//    вручную заглушка 4.5/0, сортировка по нему была бы нечестной.
// Внутри одного уровня порядок стабилен (Array.sort в всех современных
// браузерах stable) — то есть без разницы по всем 4 пунктам компании
// остаются в том порядке, что и в таблице, как раньше.
function activityScore(c) {
  const site = c.site ? 1 : 0;
  const social = [c.telegram, c.tgcontact, c.whatsapp, c.vk, c.instagram].filter(Boolean).length;
  const marketplaces = [c.avito, c.drom, c.autoru].filter(Boolean).length;
  const maps = [c.yandex, c.google, c.gis2].filter(Boolean).length;
  const reviews = c.reviews > 0 ? 1 : 0;
  return site + social + marketplaces + maps + reviews;
}
function compareCompanies(a, b) {
  const af = a.featured ? 1 : 0, bf = b.featured ? 1 : 0;
  if (af !== bf) return bf - af;
  const ao = a.onboarded ? 1 : 0, bo = b.onboarded ? 1 : 0;
  if (ao !== bo) return bo - ao;
  const ae = a.egrulVerified ? 1 : 0, be = b.egrulVerified ? 1 : 0;
  if (ae !== be) return be - ae;
  return activityScore(b) - activityScore(a);
}

// T-14 (18.08.2026): true, если браузер явно просит экономить трафик
// (Data Saver / медленное 2G) — единственный случай, когда заменяем
// автоплей-видео на статичный кадр. navigator.connection есть не везде
// (Safari/iOS его не поддерживает вовсе) — там просто ведём себя как
// раньше, это осознанный фолбэк, а не баг.
function wantsLiteVideo() {
  const c = navigator.connection || navigator.webkitConnection || navigator.mozConnection;
  if (!c) return false;
  return !!c.saveData || /2g/.test(c.effectiveType || '');
}

// Пагинация каталога — 18.08.2026, по запросу пользователя: "нужна
// навигация пролистывания каталога для быстрого перемещения по каталогу".
// 109+ компаний одним бесконечным списком неудобно листать, особенно на
// мобильном. Разбито по PAGE_SIZE штук на страницу + номера страниц внизу
// (и продублированы вверху списка) — стандартный паттерн каталогов/
// маркетплейсов, привычнее, чем "показать ещё" или бесконечный скролл, и
// не требует IntersectionObserver. currentFilteredList хранит ПОЛНЫЙ
// отфильтрованный список (без среза по странице) — applyFilters()
// пересчитывает его и всегда возвращает на страницу 1 (иначе после смены
// фильтра можно было бы залипнуть на пустой странице 5 из 2).
let currentFilteredList = COMPANIES;
let currentPage = 1;
const PAGE_SIZE = 20;

function renderCompanies(list) {
  currentFilteredList = list;
  currentPage = 1;
  // 24.08.2026 (репорт пользователя: "не меняется цифра Компаний в
  // каталоге"): та цифра в верхней плашке статистики — общий размер
  // каталога, зашитый в HTML при сборке (update_site.py), она намеренно
  // не привязана к фильтрам. Здесь — отдельный счётчик прямо в заголовке
  // каталога, куда пользователя приводит автоскролл после фильтра (см.
  // filterDir() выше): "Найдено: N", только когда список ДЕЙСТВИТЕЛЬНО
  // сужен относительно полного каталога, иначе пусто — не дублировать
  // цифру из плашки статистики, когда фильтров нет.
  const countEl = document.getElementById('resultsCount');
  if (countEl) countEl.textContent = list.length < COMPANIES.length ? `— найдено: ${list.length}` : '';
  renderPage();
}

function goToPage(n) {
  const totalPages = Math.max(1, Math.ceil(currentFilteredList.length / PAGE_SIZE));
  currentPage = Math.min(Math.max(1, n), totalPages);
  renderPage();
  document.getElementById('companies-list')?.scrollIntoView({behavior: 'smooth', block: 'start'});
}

function renderPage() {
  const el = document.getElementById('companies-list');
  if (!el) return;
  const sorted = [...currentFilteredList].sort(compareCompanies);
  const totalPages = Math.max(1, Math.ceil(sorted.length / PAGE_SIZE));
  if (currentPage > totalPages) currentPage = totalPages;
  const pageItems = sorted.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);
  const cardsHtml = pageItems.map((c, idx) => {
    const isTop = c.featured;
    const tags = c.directions.slice(0,3).map(d=>`<span class="tag">🌍 ${d}</span>`).join('') +
                 c.tags.slice(0,2).map(t=>`<span class="tag">${t}</span>`).join('');
    // Приоритет кнопки "написать" — 14.08.2026, по прямому указанию
    // пользователя: Telegram → WhatsApp → VK → Instagram → сайт → телефон.
    // ВАЖНО (уточнено 14.08.2026): поле c.telegram — это КАНАЛ/ГРУППА
    // компании (то, что находит поиск агента), у канала нет чата, написать
    // напрямую нельзя. Поэтому кнопка "написать" использует ОТДЕЛЬНОЕ поле
    // c.tgcontact (личный аккаунт/бот, колонка AE в таблице) — оно
    // заполняется скриптом fix_telegram_contact_check.py, который ищет
    // личный контакт в описании канала, НЕ трогая само поле telegram
    // (канал остаётся как есть и показывается отдельной иконкой ниже, см.
    // reviewLinks). Если tgcontact пуст — просто идём дальше по цепочке
    // приоритета, а не в канал, где писать нельзя.
    // "Связаться" без ссылки (мёртвая кнопка) убрана — вместо неё честный
    // fallback на телефон (если есть) или явная пометка, что контактов нет.
    const contact = c.tgcontact
      ? `<a href="https://t.me/${c.tgcontact}" target="_blank"><button class="btn-primary">Написать в TG</button></a>`
      : c.whatsapp
      ? `<a href="${c.whatsapp}" target="_blank"><button class="btn-primary">Написать в WhatsApp</button></a>`
      : c.vk
      ? `<a href="${c.vk}" target="_blank"><button class="btn-primary">Написать в VK</button></a>`
      : c.instagram
      ? `<a href="${c.instagram}" target="_blank"><button class="btn-primary">Написать в Instagram</button></a>`
      : c.site
      ? `<a href="${c.site}" target="_blank"><button class="btn-primary">Перейти на сайт</button></a>`
      : (c.phone && c.phone !== '-')
      ? `<button type="button" class="btn-primary phone-reveal" data-phone="${c.phone}" onclick="revealPhone(this)">📞 Показать номер</button>`
      : `<button class="btn-primary" disabled style="opacity:.5;cursor:default;">Контакты уточняются</button>`;
    const phone = (c.phone && c.phone !== '-')
      ? `<div class="meta-item"><button type="button" class="phone-reveal" data-phone="${c.phone}" onclick="revealPhone(this)">📞 Показать номер</button></div>`
      : '';
    // Реальный логотип компании — 17.08.2026, по запросу пользователя
    // ("лейб можно брать с тг канала например, с сайта и прикреплять в
    // каталоге в карточке компании"). c.avatar по-прежнему может быть
    // 2-3-буквенным инициалом с цветным фоном (как у всех остальных
    // компаний) — тогда рендерим как раньше. Если же в это поле записан
    // URL картинки (взятый с логотипа сайта/аватарки TG-канала), рендерим
    // настоящий <img> вместо инициалов. Обратной совместимости это не
    // ломает — старые карточки avatar не начинается на "http", идут
    // старым путём.
    const avatarHtml = (c.avatar || '').startsWith('http')
      ? `<div class="card-avatar has-logo"><img src="${c.avatar}" alt="${c.name}" loading="lazy"></div>`
      : `<div class="card-avatar ${c.color}">${c.avatar}</div>`;
    // Кнопки-иконки на реальные карточки компании на картах/справочниках.
    // Показываем только те площадки, где карточка реально найдена —
    // никаких выдуманных ссылок или рейтингов на кнопке.
    // T-24 (21.08.2026): иконки 2ГИС/Авито/Дром раньше грузились с чужих
    // доменов (hotlink) — риск, что домен поменяет путь/введёт 404 без
    // предупреждения, плюс лишний DNS/TLS-хендшейк на сторонний хост на
    // каждую карточку. Скачаны и лежат локально в /platform-icons/.
    // Yandex/Google/VK/Instagram/Avto.ru/Telegram — уже были инлайн-SVG,
    // хотлинка не было, не трогали.
    const reviewLinks = [
      // Канал/группа Telegram компании (не для "написать" — см. contact
      // выше, там отдельное поле tgcontact) — просто ссылка подписаться/
      // почитать, если он найден.
      c.telegram ? `<a href="https://t.me/${c.telegram}" target="_blank" class="review-icon-btn review-telegram" title="Telegram-канал"><svg viewBox="0 0 24 24" width="24" height="24"><path fill="#29a9eb" d="M11.944 0A12 12 0 0 0 0 12a12 12 0 0 0 12 12 12 12 0 0 0 12-12A12 12 0 0 0 12 0a12 12 0 0 0-.056 0zm4.962 7.224c.1-.002.321.023.465.14a.506.506 0 0 1 .171.325c.016.093.036.306.02.472-.18 1.898-.962 6.502-1.36 8.627-.168.9-.499 1.201-.82 1.23-.696.065-1.225-.46-1.9-.902-1.056-.693-1.653-1.124-2.678-1.8-1.185-.78-.417-1.21.258-1.91.177-.184 3.247-2.977 3.307-3.23.007-.032.014-.15-.056-.212s-.174-.041-.249-.024c-.106.024-1.793 1.14-5.061 3.345-.48.33-.913.49-1.302.48-.428-.008-1.252-.241-1.865-.44-.752-.245-1.349-.374-1.297-.789.027-.216.325-.437.893-.663 3.498-1.524 5.83-2.529 6.998-3.014 3.332-1.386 4.025-1.627 4.476-1.635z"/></svg></a>` : '',
      c.yandex ? `<a href="${c.yandex}" target="_blank" class="review-icon-btn review-yandex" title="Яндекс Карты"><svg width="22" height="22" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M8 1C4.6862 1 2 3.6862 2 7C2 8.6563 2.6711 10.156 3.7565 11.2417C4.8422 12.328 7.4 13.9 7.55 15.55C7.57249 15.7974 7.7516 16 8 16C8.2484 16 8.42751 15.7974 8.45 15.55C8.6 13.9 11.1578 12.328 12.2435 11.2417C13.3289 10.156 14 8.6563 14 7C14 3.6862 11.3138 1 8 1Z" fill="#FF4433"/><path d="M8.00002 9.10015C9.15982 9.10015 10.1 8.15994 10.1 7.00015C10.1 5.84035 9.15982 4.90015 8.00002 4.90015C6.84023 4.90015 5.90002 5.84035 5.90002 7.00015C5.90002 8.15994 6.84023 9.10015 8.00002 9.10015Z" fill="white"/></svg></a>` : '',
      c.google ? `<a href="${c.google}" target="_blank" class="review-icon-btn review-google" title="Google Карты"><svg viewBox="0 0 24 24" width="18" height="18"><path fill="#4285f4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/><path fill="#34a853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#fbbc05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/><path fill="#ea4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/></svg></a>` : '',
      c.gis2 ? `<a href="${c.gis2}" target="_blank" class="review-icon-btn review-2gis" title="2ГИС"><img src="/platform-icons/2gis.png" alt="2ГИС" width="28" height="28" style="object-fit:contain;border-radius:6px;"></a>` : '',
      c.instagram ? `<a href="${c.instagram}" target="_blank" class="review-icon-btn review-instagram" title="Instagram"><svg viewBox="0 0 24 24" width="16" height="16"><path fill="#fff" d="M7.0301.084c-1.2768.0602-2.1487.264-2.911.5634-.7888.3075-1.4575.72-2.1228 1.3877-.6652.6677-1.075 1.3368-1.3802 2.127-.2954.7638-.4956 1.6365-.552 2.914-.0564 1.2775-.0689 1.6882-.0626 4.947.0062 3.2586.0206 3.6671.0825 4.9473.061 1.2765.264 2.1482.5635 2.9107.308.7889.72 1.4573 1.388 2.1228.6679.6655 1.3365 1.0743 2.1285 1.38.7632.295 1.6361.4961 2.9134.552 1.2773.056 1.6884.069 4.9462.0627 3.2578-.0062 3.668-.0207 4.9478-.0814 1.28-.0607 2.147-.2652 2.9098-.5633.7889-.3086 1.4578-.72 2.1228-1.3881.665-.6682 1.0745-1.3378 1.3795-2.1284.2957-.7632.4966-1.636.552-2.9124.056-1.2809.0692-1.6898.063-4.948-.0063-3.2583-.021-3.6668-.0817-4.9465-.0607-1.2797-.264-2.1487-.5633-2.9117-.3084-.7889-.72-1.4568-1.3876-2.1228C21.2982 1.33 20.628.9208 19.8378.6165 19.074.321 18.2017.1197 16.9244.0645 15.6471.0093 15.236-.005 11.977.0014 8.718.0076 8.31.0215 7.0301.0839m.1402 21.6932c-1.17-.0509-1.8053-.2453-2.2287-.408-.5606-.216-.96-.4771-1.3819-.895-.422-.4178-.6811-.8186-.9-1.378-.1644-.4234-.3624-1.058-.4171-2.228-.0595-1.2645-.072-1.6442-.079-4.848-.007-3.2037.0053-3.583.0607-4.848.05-1.169.2456-1.805.408-2.2282.216-.5613.4762-.96.895-1.3816.4188-.4217.8184-.6814 1.3783-.9003.423-.1651 1.0575-.3614 2.227-.4171 1.2655-.06 1.6447-.072 4.848-.079 3.2033-.007 3.5835.005 4.8495.0608 1.169.0508 1.8053.2445 2.228.408.5608.216.96.4754 1.3816.895.4217.4194.6816.8176.9005 1.3787.1653.4217.3617 1.056.4169 2.2263.0602 1.2655.0739 1.645.0796 4.848.0058 3.203-.0055 3.5834-.061 4.848-.051 1.17-.245 1.8055-.408 2.2294-.216.5604-.4763.96-.8954 1.3814-.419.4215-.8181.6811-1.3783.9-.4224.1649-1.0577.3617-2.2262.4174-1.2656.0595-1.6448.072-4.8493.079-3.2045.007-3.5825-.006-4.848-.0608M16.953 5.5864A1.44 1.44 0 1 0 18.39 4.144a1.44 1.44 0 0 0-1.437 1.4424M5.8385 12.012c.0067 3.4032 2.7706 6.1557 6.173 6.1493 3.4026-.0065 6.157-2.7701 6.1506-6.1733-.0065-3.4032-2.771-6.1565-6.174-6.1498-3.403.0067-6.156 2.771-6.1496 6.1738M8 12.0077a4 4 0 1 1 4.008 3.9921A3.9996 3.9996 0 0 1 8 12.0077"/></svg></a>` : '',
      c.vk ? `<a href="${c.vk}" target="_blank" class="review-icon-btn review-vk" title="ВКонтакте"><svg viewBox="0 0 24 24" width="24" height="24"><path fill="#0077ff" d="m9.489.004.729-.003h3.564l.73.003.914.01.433.007.418.011.403.014.388.016.374.021.36.025.345.03.333.033c1.74.196 2.933.616 3.833 1.516.9.9 1.32 2.092 1.516 3.833l.034.333.029.346.025.36.02.373.025.588.012.41.013.644.009.915.004.98-.001 3.313-.003.73-.01.914-.007.433-.011.418-.014.403-.016.388-.021.374-.025.36-.03.345-.033.333c-.196 1.74-.616 2.933-1.516 3.833-.9.9-2.092 1.32-3.833 1.516l-.333.034-.346.029-.36.025-.373.02-.588.025-.41.012-.644.013-.915.009-.98.004-3.313-.001-.73-.003-.914-.01-.433-.007-.418-.011-.403-.014-.388-.016-.374-.021-.36-.025-.345-.03-.333-.033c-1.74-.196-2.933-.616-3.833-1.516-.9-.9-1.32-2.092-1.516-3.833l-.034-.333-.029-.346-.025-.36-.02-.373-.025-.588-.012-.41-.013-.644-.009-.915-.004-.98.001-3.313.003-.73.01-.914.007-.433.011-.418.014-.403.016-.388.021-.374.025-.36.03-.345.033-.333c.196-1.74.616-2.933 1.516-3.833.9-.9 2.092-1.32 3.833-1.516l.333-.034.346-.029.36-.025.373-.02.588-.025.41-.012.644-.013.915-.009ZM6.79 7.3H4.05c.13 6.24 3.25 9.99 8.72 9.99h.31v-3.57c2.01.2 3.53 1.67 4.14 3.57h2.84c-.78-2.84-2.83-4.41-4.11-5.01 1.28-.74 3.08-2.54 3.51-4.98h-2.58c-.56 1.98-2.22 3.78-3.8 3.95V7.3H10.5v6.92c-1.6-.4-3.62-2.34-3.71-6.92Z"/></svg></a>` : '',
      c.avito ? `<a href="${c.avito}" target="_blank" class="review-icon-btn review-avito" title="Авито"><img src="/platform-icons/avito.png" alt="Авито" width="26" height="26" style="object-fit:contain;"></a>` : '',
      c.drom ? `<a href="${c.drom}" target="_blank" class="review-icon-btn review-drom" title="Дром"><img src="/platform-icons/drom.png" alt="Дром" width="28" height="28" style="object-fit:contain;border-radius:6px;"></a>` : '',
      c.autoru ? `<a href="${c.autoru}" target="_blank" class="review-icon-btn review-autoru" title="Авто.ру"><svg width="26" height="26" viewBox="0 0 64.125 64.125" xmlns="http://www.w3.org/2000/svg" style="border-radius:6px;"><path fill="#FF1700" d="M0 0h64.125v64.125H0z"/><path fill-rule="evenodd" clip-rule="evenodd" d="M18.184 22.822c-.587 0-1.147.25-1.54.687l-5.062 5.63v6.24c0 1.143.928 2.07 2.072 2.07h.209a5.628 5.628 0 0 1 11.043 0H38.89a5.628 5.628 0 0 1 11.043 0h1.007a2.072 2.072 0 0 0 2.071-2.07v-3.33a.797.797 0 0 0-.612-.775l-8.82-2.106-8.773-5.985a2.071 2.071 0 0 0-1.168-.36H18.185zm6.282 18.133H39.33a5.627 5.627 0 0 0 10.163 0h1.447a5.577 5.577 0 0 0 5.577-5.577v-3.33a4.302 4.302 0 0 0-3.304-4.184l-8.192-1.956-8.24-5.621a5.577 5.577 0 0 0-3.143-.97H18.185c-1.582 0-3.09.671-4.148 1.848l-5.256 5.847a2.746 2.746 0 0 0-.704 1.836v6.53a5.577 5.577 0 0 0 5.577 5.577h.65a5.627 5.627 0 0 0 10.162 0zm19.946-4.54a2.121 2.121 0 1 0 0 4.242 2.121 2.121 0 0 0 0-4.242zm-27.148 2.12a2.121 2.121 0 1 1 4.242.001 2.121 2.121 0 0 1-4.242 0z" fill="#fff"/></svg></a>` : ''
    ].join('');
    return `
    <article class="company-card ${isTop?'top':''} ${idx<2?'card-video-bg':''}" data-link="${c.link||'#'}" style="cursor:${c.link&&c.link!=='#'?'pointer':'default'}">
      <div class="card-header">
        ${avatarHtml}
        <div class="card-info">
          <div class="card-top">
            <div class="card-name">${c.name}</div>
            ${isTop?'<span class="top-badge">★ Рекомендуем</span>':''}
            ${c.egrulVerified
              ? `<span class="verified">✓ В ЕГРЮЛ с ${c.egrulYear} года</span>`
              : `<span class="verified verified-basic">✓ Проверена активность</span>`}
          </div>
          <div class="card-desc">${c.description}</div>
          <div class="card-tags">${tags}</div>
        </div>
        <div class="card-right">
          ${(() => {
            // 14.08.2026: старый блок рейтинга/числа отзывов убран — это
            // была агрегированная, непроверяемая цифра ("липовые отзывы").
            // 17.08.2026, по прямому запросу пользователя: кнопка больше не
            // ведёт на сторонние площадки — отзыв создаётся прямо у нас
            // (форма в модалке openReviewModal), проходит модерацию и
            // публикуется на карточке. Если уже есть опубликованные
            // отзывы — показываем их количество на самой кнопке.
            const n = (c.reviewsList || []).length;
            const label = n ? `★ ${n} ${reviewWordRu(n)}` : '✍️ Оставить отзыв';
            return `<button type="button" class="leave-review-btn" onclick="event.stopPropagation(); openReviewModal(${c.id})">${label}</button>`;
          })()}
        </div>
      </div>
      <div class="card-footer">
        <div class="card-meta">
          <div class="meta-item">Опыт: <strong>${c.years} лет</strong></div>
          <div class="meta-item">Доставлено: <strong>${c.delivered}</strong></div>
          ${phone}
        </div>
        <div class="card-actions">
          ${reviewLinks ? `<div class="review-links">${reviewLinks}</div>` : ''}
          ${contact}
        </div>
      </div>
    </article>`;
  });
  // Видео-фон за 1-й/2-й карточкой — 14.08.2026, по запросу пользователя:
  // ОДНО видео на высоту обеих карточек вместе, во всю ширину экрана (как
  // видео-фон у Калькулятора/Разослать запрос выше), а не два отдельных
  // видео по одному на карточку. Первые 2 карточки (по текущей сортировке
  // — сейчас топ/рекомендуемые) оборачиваются в .companies-video-wrap с
  // общим <video>, остальные карточки идут после как обычно.
  // 18.08.2026: с пагинацией видео-фон имеет смысл только на 1-й странице
  // (топ-компании всегда там благодаря compareCompanies) — на остальных
  // страницах первые 2 карточки этой страницы никак не "топ", видео за
  // ними было бы просто случайным.
  const videoCards = currentPage === 1 ? cardsHtml.slice(0, 2).join('') : '';
  const restCards = currentPage === 1 ? cardsHtml.slice(2).join('') : cardsHtml.join('');
  // T-14 (18.08.2026, аудит TASKS.md): 2.8МБ автоплей-видео на мобильном
  // трафике. В этой же сессии пользователь явно просил, чтобы видео на
  // мобильном было хорошо видно — поэтому не отключаем его на мобильном
  // по умолчанию, это противоречило бы прямому запросу. Но у части
  // пользователей явно включена экономия трафика (Data Saver в браузере/
  // ОС, navigator.connection.saveData) — для них этот сигнал уважаем и
  // показываем статичный кадр вместо тяжёлого видео.
  const videoBg = wantsLiteVideo()
    ? `<img class="companies-bg-video" src="/videos/card-bg-poster.jpg" alt="" loading="lazy">`
    : `<video class="companies-bg-video" autoplay muted loop playsinline preload="metadata" poster="/videos/card-bg-poster.jpg"><source src="/videos/card-bg.mp4" type="video/mp4"></video>`;
  const videoBlock = videoCards ? `
    <div class="companies-video-wrap">
      ${videoBg}
      <div class="companies-bg-overlay"></div>
      <div class="companies-video-content">${videoCards}</div>
    </div>` : '';
  // T-63: пагинация сверху тоже (не только снизу) — переключение страницы
  // без скролла в конец текущей.
  const topPagerHtml = buildPagerHtml(totalPages).replace('class="pager"', 'class="pager pager-top"');
  el.innerHTML = topPagerHtml + videoBlock + restCards + buildPagerHtml(totalPages);
  document.querySelector('.companies-title').textContent = `Компании в каталоге (${sorted.length})`;
}

// Разметка пагинации — простые кнопки Назад/1..N/Вперёд. При большом числе
// страниц (>7) показываем только окно вокруг текущей + первую/последнюю с
// многоточиями, чтобы не растягивать ряд на весь экран.
function buildPagerHtml(totalPages) {
  if (totalPages <= 1) return '';
  const pages = [];
  const add = n => pages.push(n);
  const win = 1;
  for (let n = 1; n <= totalPages; n++) {
    if (n === 1 || n === totalPages || (n >= currentPage - win && n <= currentPage + win)) add(n);
    else if (pages[pages.length - 1] !== '…') add('…');
  }
  const btn = (n, label, disabled) =>
    `<button type="button" class="pager-btn" ${disabled ? 'disabled' : `onclick="goToPage(${n})"`}>${label}</button>`;
  const numBtns = pages.map(n => n === '…'
    ? `<span class="pager-ellipsis">…</span>`
    : `<button type="button" class="pager-btn ${n === currentPage ? 'pager-current' : ''}" onclick="goToPage(${n})">${n}</button>`
  ).join('');
  return `<nav class="pager" aria-label="Страницы каталога">
    ${btn(currentPage - 1, '‹ Назад', currentPage === 1)}
    ${numBtns}
    ${btn(currentPage + 1, 'Вперёд ›', currentPage === totalPages)}
  </nav>`;
}

// DIR_MAP — общий словарь ключ->название направления, используется и
// шапкой (.dir чипы, одиночный выбор), и сайдбаром (чекбоксы, множественный
// выбор). checkedDirs по умолчанию = все ключи (все чекбоксы отмечены =
// сайдбар не сужает список, как и было визуально раньше) — но раньше
// чекбоксы были просто картинкой, ни к чему не подключённой, с ВЫДУМАННЫМИ
// цифрами вроде "Китай (89)" (реальных компаний с Китаем — на порядок
// меньше). Теперь и подключены, и цифры настоящие, считаются из COMPANIES.
const DIR_MAP = {china:'Китай',korea:'Корея',japan:'Япония',usa:'США',uae:'ОАЭ',europe:'Европа',canada:'Канада',georgia:'Грузия'};
let activeDir = 'all';
let checkedDirs = new Set(Object.keys(DIR_MAP));

// T-64 (21.08.2026): фильтр по городу офиса. '__none__' — отдельное
// значение для компаний без определённого города (не выкидываем их из
// каталога молча, честно показываем как отдельную группу).
let selectedCity = 'all';

function populateCityFilter() {
  const sel = document.getElementById('cityFilter');
  if (!sel) return;
  const cities = [...new Set(COMPANIES.map(c => c.city).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'ru'));
  const noneCount = COMPANIES.filter(c => !c.city).length;
  let html = '<option value="all">Все города</option>';
  html += cities.map(c => `<option value="${c}">${c}</option>`).join('');
  if (noneCount) html += `<option value="__none__">Без указания города (${noneCount})</option>`;
  sel.innerHTML = html;
}

function onCityFilterChange(sel) {
  selectedCity = sel.value;
  applyFilters();
}

function filterDir(el, dir) {
  document.querySelectorAll('.dir').forEach(d=>d.classList.remove('active'));
  el.classList.add('active');
  activeDir = dir;
  applyFilters();
  // 24.08.2026 (репорт пользователя: "карточки не пересчитываются по
  // выбранному направлению"): фильтрация на самом деле всегда работала
  // правильно — баг был в другом: кнопки направлений стоят у самого верха
  // страницы, а каталог (#catalog) далеко внизу, после калькулятора и
  // статистики. Без автоскролла пользователь после клика видит тот же
  // экран, что и до клика, и решает, что ничего не изменилось — хотя
  // список карточек ниже уже пересчитан. doSearch() такой скролл уже
  // делал, сюда добавили то же самое для консистентности.
  document.getElementById('catalog')?.scrollIntoView({behavior: 'smooth', block: 'start'});
}

// 24.08.2026 (по вопросу пользователя: "если компания записана на
// английском, можно ли писать по-русски и предложит вариант компании на
// английском"): раньше поиск был обычным substring-совпадением — запрос
// на кириллице никак не находил компанию с латинским названием
// (Westmotors, VladTD и т.п.). Добавлена простая транслитерация запроса
// кириллица -> латиница (посимвольная, без словаря) — если введённый
// текст на кириллице, пробуем ЕЩЁ и его латинскую транслитерацию против
// названия/описания. Точность не 100% (русское "в" может значить и v, и
// w, "х" — и h, и kh), но покрывает большинство обычных случаев ("вестмо
// торс" -> "vestmotors" всё равно не совпадёт с "westmotors" — это
// известное ограничение транслитерации, не баг).
// TEST-EXTRACT-START (test_search.js вырезает отсюда досюда для юнит-теста
// поиска — держите этот блок самодостаточным, без зависимостей на DOM или
// на остальной код файла, иначе извлечение сломается).
const TRANSLIT_MAP = {
  а:'a', б:'b', в:'v', г:'g', д:'d', е:'e', ё:'e', ж:'zh', з:'z', и:'i',
  й:'y', к:'k', л:'l', м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t',
  у:'u', ф:'f', х:'h', ц:'ts', ч:'ch', ш:'sh', щ:'sch', ъ:'', ы:'y',
  ь:'', э:'e', ю:'yu', я:'ya',
};
function translit(s) {
  return s.split('').map(ch => TRANSLIT_MAP[ch] ?? ch).join('');
}

// 24.08.2026 (репорт пользователя: "забиваю май авто и не находит"):
// буквенная транслитерация выше не ловит ФОНЕТИЧЕСКОЕ написание — "MY"
// произносится как английское "my" (рифмуется с "eye"), по-русски это
// на слух "май", а не побуквенная транслитерация "м"+"ы". Для таких
// случаев словарь ничем не заменить — точечно прописываем известные
// произносимые не по правилам названия здесь по мере репортов
// пользователей, ключ — точное название компании как в таблице.
const SEARCH_ALIASES = {
  'my avto': ['май авто', 'майавто'],
};
function matchesQuery(c, q, qTranslit) {
  const name = c.name.toLowerCase();
  const desc = c.description.toLowerCase();
  if (name.includes(q) || desc.includes(q) ||
      c.directions.some(d=>d.toLowerCase().includes(q)) || c.tags.some(t=>t.toLowerCase().includes(q))) {
    return true;
  }
  if (qTranslit !== q && (name.includes(qTranslit) || desc.includes(qTranslit))) return true;
  const aliases = SEARCH_ALIASES[name];
  return !!aliases && aliases.some(a => a.includes(q) || q.includes(a));
}
// TEST-EXTRACT-END

function applyFilters() {
  let list = COMPANIES;
  if (activeDir !== 'all' && DIR_MAP[activeDir]) list = list.filter(c=>c.directions.includes(DIR_MAP[activeDir]));
  if (checkedDirs.size < Object.keys(DIR_MAP).length) {
    const allowed = [...checkedDirs].map(k=>DIR_MAP[k]);
    list = list.filter(c=>c.directions.some(d=>allowed.includes(d)));
  }
  // T-64: фильтр по городу офиса.
  if (selectedCity !== 'all') {
    list = selectedCity === '__none__' ? list.filter(c => !c.city) : list.filter(c => c.city === selectedCity);
  }
  // Поиск — 14.08.2026, расширен по запросу пользователя: раньше искал
  // только по названию/описанию/направлению, теперь ещё и по тегам
  // ("хэштегам" вроде "Под ключ", "Без посредников"). Работает для любых
  // букв/цифр (кириллица/латиница/цифры вперемешку) "из коробки" — это
  // обычный регистронезависимый substring-поиск через .includes(), в
  // JS toLowerCase()/includes() не завязаны на конкретный алфавит.
  const q = document.getElementById('mainSearch')?.value.toLowerCase().trim();
  if (q) list = list.filter(c => matchesQuery(c, q, translit(q)));
  renderCompanies(list);
}

// Автоподсказки под полем поиска — 14.08.2026, по запросу пользователя
// ("автоматическая подсказка на выбор"). Ищет по тому же набору полей,
// что и сам поиск (имя/теги/направления), показывает до 8 совпадений,
// клик по подсказке подставляет точное название в поле, применяет фильтр
// и прокручивает к каталогу — не нужно листать весь отфильтрованный
// список руками, чтобы найти конкретную компанию по имени.
function updateSearchSuggestions(rawQuery) {
  const box = document.getElementById('searchSuggestions');
  if (!box) return;
  const q = rawQuery.toLowerCase().trim();
  if (!q) { box.style.display = 'none'; box.innerHTML = ''; return; }
  const qTranslit = translit(q);
  const matches = COMPANIES.filter(c => {
    const name = c.name.toLowerCase();
    if (name.includes(q) ||
        c.tags.some(t => t.toLowerCase().includes(q)) ||
        c.directions.some(d => d.toLowerCase().includes(q))) return true;
    if (qTranslit !== q && name.includes(qTranslit)) return true;
    const aliases = SEARCH_ALIASES[name];
    return !!aliases && aliases.some(a => a.includes(q) || q.includes(a));
  }).slice(0, 8);
  if (!matches.length) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.innerHTML = matches.map(c => {
    const meta = c.directions[0] ? `🌍 ${c.directions[0]}` : (c.tags[0] || '');
    return `<div class="search-suggestion-item" data-name="${c.name.replace(/"/g,'&quot;')}">` +
      `<span class="sugg-name">${c.name}</span><span class="sugg-meta">${meta}</span></div>`;
  }).join('');
  box.style.display = 'block';
}

document.getElementById('searchSuggestions')?.addEventListener('click', e => {
  const item = e.target.closest('.search-suggestion-item');
  if (!item) return;
  const input = document.getElementById('mainSearch');
  input.value = item.dataset.name;
  applyFilters();
  document.getElementById('searchSuggestions').style.display = 'none';
  document.getElementById('catalog')?.scrollIntoView({behavior: 'smooth'});
});

document.addEventListener('click', e => {
  if (!e.target.closest('.search-wrap')) {
    const box = document.getElementById('searchSuggestions');
    if (box) box.style.display = 'none';
  }
});

document.getElementById('mainSearch')?.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    const box = document.getElementById('searchSuggestions');
    if (box) box.style.display = 'none';
  }
});

function revealPhone(btn) {
  // Номер не палим в открытую в тексте страницы — только по явному клику.
  var phone = btn.dataset.phone;
  if (!phone) return;
  btn.outerHTML = `<a href="tel:${phone.replace(/[^\d+]/g,'')}" class="phone-reveal phone-revealed">📞 ${phone}</a>`;
}

