// T-63 (21.08.2026): плавающая кнопка быстрой навигации — до каталога с
// начала страницы нужно проскроллить мимо hero/калькулятора/промо-видео/
// формы заявки, это и была жалоба "долго листать вниз". Кнопка появляется
// после небольшого скролла и работает в обе стороны: выше каталога —
// прыгает к нему, внутри/ниже каталога — прыгает наверх страницы.
function quickNavClick() {
  const btn = document.getElementById('quickNavBtn');
  if (btn && btn.dataset.mode === 'up') {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  } else {
    document.getElementById('catalog')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

function updateQuickNav() {
  const btn = document.getElementById('quickNavBtn');
  const catalog = document.getElementById('catalog');
  if (!btn || !catalog) return;
  const scrollY = window.scrollY || window.pageYOffset;
  if (scrollY < 300) {
    btn.classList.remove('visible');
    return;
  }
  btn.classList.add('visible');
  const catalogTop = catalog.getBoundingClientRect().top + scrollY;
  if (scrollY < catalogTop - 80) {
    btn.textContent = '↓ К каталогу';
    btn.dataset.mode = 'down';
  } else {
    btn.textContent = '↑ Наверх';
    btn.dataset.mode = 'up';
  }
}

// requestAnimationFrame-throttling — скролл стреляет событиями чаще, чем
// нужно пересчитывать позицию кнопки, без троттлинга это лишняя нагрузка
// на каждый пиксель скролла.
let _quickNavTicking = false;
window.addEventListener('scroll', () => {
  if (!_quickNavTicking) {
    requestAnimationFrame(() => { updateQuickNav(); _quickNavTicking = false; });
    _quickNavTicking = true;
  }
});
